mb:micro.mb:input-type:
bootstrap(deps: {
  root: HTMLElement, hash: string, persistence: Persistence, settings: SettingsStore,
  codec: {decode, encode}, dialogs: DialogHost, announcer: Announcer,
  fetchPuzzle: () => Promise<{puzzle:number[], solution:number[]}>,
  history: {replaceState: (url: string) => void}
}) -> Promise<{ok: true, store: Store} | {ok: false, reason: string}>

mb:micro.mb:pseudocode:
async function bootstrap(deps) {
    renderInertSkeleton(deps.root);
    const url   = deps.hash ? await deps.codec.decode(deps.hash) : null;
    const local = deps.persistence.restore();
    const decision = await resolveConflict(url, local, deps);   // CR1..CR5, evaluated once
    let session = decision.session;
    if (!session) session = await createNewSession(deps);        // step 7
    if (!session) return {ok:false, reason:"no-session"};
    const store = createStore(session);
    enableAdapters(store);                                       // step 8
    if (decision.consumedFragment) deps.history.replaceState(cleanUrl());   // step 9
    return {ok:true, store};
}

if (!url?.ok) { if (url) await notifyDecodeFailure(url.code); return {session: local.session, consumedFragment: !!url}; }
if (!local.ok) return {session: url.state -> session, consumedFragment: true};

if (!sameGivens(url, local))                       // CR1
    { archive(local); toastUndo(8000); return adopt(url); }

let core = local;                                   // CR2 / CR3
if (differentCore(url, local))
    core = await dialogs.chooseCore(summaries(url, local));

let notes = local.notes;                            // CR4, only when the URL carried them
if (url.state.notes) notes = await mergeNotes(local.notes, url.state.notes, dialogs);
// omission is never deletion (V4-10)
return {session: combine(core, notes), consumedFragment: true};

async function createNewSession(deps) {
    if (navigator.onLine === false) return showRetryPanel(deps, "offline");
    for (let attempt = 1; attempt <= 2; attempt++) {
        const ctl = new AbortController();
        const timer = setTimeout(() => ctl.abort(), 10_000);
        try {
            const res = await deps.fetchPuzzle({signal: ctl.signal});
            if (res.status >= 500) throw new RetryableError();
            if (!res.ok) return showRetryPanel(deps, "server");      // 4xx: no retry
            const data = await res.json();
            if (!isValidPuzzle(data.puzzle)) return showRetryPanel(deps, "server");
            return sessionFromPuzzle(data.puzzle);                   // solution discarded
        } catch (e) {
            if (attempt === 1) { await delay(1000); continue; }
            return showRetryPanel(deps, "network");
        } finally { clearTimeout(timer); }
    }
}

function showRetryPanel(deps, cause) {
    const panel = renderOutsideBoard(MESSAGES[cause]);
    const btn = panel.querySelector("button");        // 48x48 minimum
    btn.addEventListener("click", () => retryBootstrap(deps));
    btn.focus();
    window.addEventListener("online", () => btn.dataset.highlight = "1", {once: true});
    deps.announcer.announce("session", MESSAGES[cause]);
    return null;                                      // never a blank page
}

function wireLifecycle(persistence) {
    const flush = () => persistence.flushNow();
    window.addEventListener("pagehide", flush);
    document.addEventListener("visibilitychange",
        () => { if (document.visibilityState === "hidden") flush(); });
    // no beforeunload: it cannot be relied on and may block unload
}
function cleanUrl() { return location.pathname + location.search; }   // drops the fragment

mb:micro.mb:input-type:
mountShell(root, store, settings, deps: {
  dialogs: DialogHost, announcer: Announcer,
  openShare: () => void, openNotes: () => void, openSettings: () => void, openHelp: () => void
}) -> Shell

mb:micro.mb:pseudocode:
render header with one <button type="button"> per action
store.subscribe(() => {
    const solved = rules.isSolved(store.values, store.givens);
    if (solved && !wasSolved) deps.announcer.announce("completion", "퍼즐을 완성했습니다");
    root.dataset.state = solved ? "solved" : "playing";
    wasSolved = solved;
});

function onCheck() {
    const bad = rules.conflicts(store.values, store.givens);
    const done = rules.isSolved(store.values, store.givens);
    const msg = bad.size ? `규칙 위반 ${bad.size}칸`
              : done     ? "퍼즐을 완성했습니다"
                         : "지금까지 규칙 위반이 없습니다";
    deps.announcer.announce("completion", msg);
    boardView.highlightConflicts(bad);
}
// there is no solution to compare against, by construction (V4-11)

const DESTRUCTIVE = {
  newGame:        {q: "새 게임을 시작할까요? 현재 진행은 사라집니다.", run: startNewGame},
  clearAll:       {q: "입력한 숫자와 후보를 모두 지울까요?",            run: clearAllEntries},
  deleteAllNotes: {q: "메모를 모두 삭제할까요?",                        run: deleteAllNotes},
};
async function onDestructive(kind) {
    const spec = DESTRUCTIVE[kind];
    if (!spec) throw new RangeError(`unknown destructive action: ${kind}`);
    if (!(await deps.dialogs.confirm(spec.q))) return;    // cancel changes nothing
    spec.run(store);
}

const seen = Number.isInteger(settings.get().hintStripSeenCount)
           ? Math.max(0, settings.get().hintStripSeenCount) : 0;
if (seen < 3 && isDesktopIdle()) {
    showHintStrip();
    settings.set("hintStripSeenCount", seen + 1);   // consume immediately, not on dismiss
}

for each boolean field: <input type="checkbox" checked={value}>
    on change -> settings.set(key, el.checked)
touchControls: three <input type="radio" name="touchControls">
    on change -> settings.set("touchControls", el.value)
// subscribers (KeyboardAdapter, TouchAdapter) react through settings.subscribe,
// so nothing here reaches into those modules directly

import { KEYMAP } from "./keyboard-adapter.js";
renderHelp(keymap = KEYMAP):
    if (!keymap.length) throw new Error("help cannot render an empty keymap");
    build a <table> with one row per entry: combo, description
// duplicating the strings here is exactly the drift W3-R4 warns about
